"""Generate NumPy pairwise-summation vectors for the GLM-5.3 sampler host tests."""
import numpy as np
from pathlib import Path

lengths = [7, 8, 9, 127, 128, 129, 1000]
lines = [
    'const std = @import("std");',
    "",
    "// Generated by gen_numpy_pairwise_fixture.py with NumPy np.sum (float64).",
    "pub const Case = struct { values: []const f64, expected_bits: u64 };",
    "pub const cases = [_]Case{",
]
for length in lengths:
    i = np.arange(length, dtype=np.float64)
    # Mixed magnitudes make the checked reduction order visible in the result bits.
    vals = np.exp(-((i % 41.0) / 3.0))
    vals[::17] *= 2.0**-45
    expected = np.sum(vals, dtype=np.float64)
    value_expr = ",\n        ".join(f"@bitCast(@as(u64, 0x{v.view(np.uint64):016x}))" for v in vals)
    expected_bits = expected.view(np.uint64)
    lines.append(f"    .{{ .values = &.{{\n        {value_expr}\n    }}, .expected_bits = 0x{expected_bits:016x} }}, // k={length}")
lines.extend(["};", ""])
equal_terms = np.exp(np.asarray([0.0, 0.0, 0.0], dtype=np.float64))
norm = np.sum(equal_terms, dtype=np.float64)
first_mass = np.cumsum(equal_terms / norm, dtype=np.float64)[0]
below = np.nextafter(first_mass, -np.inf)
above = np.nextafter(first_mass, np.inf)
lines.extend([
    f"pub const top_p_below: f64 = @bitCast(@as(u64, 0x{below.view(np.uint64):016x}));",
    f"pub const top_p_above: f64 = @bitCast(@as(u64, 0x{above.view(np.uint64):016x}));",
    "",
])
lines.extend([
    'test "all generated NumPy fixture declarations are analyzed" {',
    "    std.testing.refAllDecls(@This());",
    "    std.testing.refAllDecls(Case);",
    "}",
    "",
])
output = Path(__file__).resolve().parents[4] / "src/families/glm_dsa/cuda/numpy_pairwise_fixture.zig"
output.write_text("\n".join(lines))
print(f"generated NumPy {np.__version__} pairwise fixtures at lengths {lengths}: {output}")
